import os
import boto3
from botocore.exceptions import ClientError

def conditional_update(payload, config=None):
    config = config or {}
    table_name = config.get("table_name") or os.environ["DYNAMODB_TABLE_NAME"]
    key = config.get("key") or payload["key"]
    attribute_updates = payload.get("updates", {})
    expected_version = payload.get("version")
    dynamodb = boto3.resource("dynamodb", region_name=config.get("region") or os.environ.get("AWS_REGION"))
    table = dynamodb.Table(table_name)
    update_expr_parts = []
    expr_attr_names = {}
    expr_attr_values = {}
    for i, (attr, value) in enumerate(attribute_updates.items()):
        name_key = f"#n{i}"
        value_key = f":v{i}"
        expr_attr_names[name_key] = attr
        expr_attr_values[value_key] = value
        update_expr_parts.append(f"{name_key} = {value_key}")
    update_expression = "SET " + ", ".join(update_expr_parts) if update_expr_parts else "SET #noop = :noop"
    if not update_expr_parts:
        expr_attr_names["#noop"] = "_noop"
        expr_attr_values[":noop"] = True
    condition_expression = None
    if expected_version is not None:
        expr_attr_names["#version"] = "version"
        expr_attr_values[":expected_version"] = expected_version
        expr_attr_values[":next_version"] = expected_version + 1
        if update_expr_parts:
            update_expression += ", #version = :next_version"
        else:
            update_expression = "SET #version = :next_version"
        condition_expression = "#version = :expected_version"
    try:
        result = table.update_item(
            Key=key,
            UpdateExpression=update_expression,
            ConditionExpression=condition_expression,
            ExpressionAttributeNames=expr_attr_names or None,
            ExpressionAttributeValues=expr_attr_values or None,
            ReturnValues="ALL_NEW",
        )
        return result.get("Attributes", result)
    except ClientError as e:
        return {"error": str(e), "code": e.response.get("Error", {}).get("Code")}
